namespace ZeldaCompanion;

internal static class GuideContent
{
    public static readonly string[] Topics=["Getting started","Play online with friends","Co-op features & limits","Controls & saving","Troubleshooting","Sharing this package","Music & MSU-1","Randomizer & progression"];
    public static (string Title,string Body)[] Sections(int topic)=>topic switch {
        0=>[
            ("1. Extract the whole ZIP","Right-click the ZIP and choose Extract All. Use a writable folder such as Documents or a folder on your desktop. Do not launch from inside the ZIP; keep all its folders together."),
            ("2. Open Zelda Companion.exe","This is the launcher in the top level of the extracted folder. Game and Relay contain supporting programs; you do not need to open those executables to play. .NET, SDL and the asset tools are already bundled."),
            ("3. Choose your own USA ROM","Use Choose ROM on the Play page. This version accepts the original, unmodified USA .sfc or .smc game, including a copier header. Other regions and ROM hacks are rejected. Game data is generated locally; no ROM download is supplied."),
            ("4. Play solo","The recommended Smooth 1080p look softens pixel edges with xBRZ and uses a 16:9 view. It is a display filter, not new HD artwork. Choose Crisp pixels or Original 4:3 if you prefer. Audio is enabled in the clean release."),
            ("A Windows notice?","This is an unsigned community application. Windows may show a SmartScreen reputation prompt. Only run a package from a source you trust. If security software blocks it, check the notification and package checksum; do not disable protection globally."),
            ("A community project","Built on the snesrev native Zelda 3 engine. No affiliation with Nintendo. Every player provides their own game data.")],
        1=>[
            ("Before you begin","Up to eight players can join. Everyone needs version 0.3.1, their own original USA ROM, matching display/aspect and gameplay settings, and the same adventure and progress/combat choices. Controls, music and name visibility are personal. Solo saves are kept separate. For Treasure Shuffle, import the same Companion recipe and select it under Online adventure."),
            ("New or continuing adventure?","Your online campaign lets you start fresh or continue a saved online profile, including a profile from the previous release. Choose the same adventure you were playing with these friends. Each player keeps their own position, consumables and saves; joining merges permanent equipment and progress. Save normally before closing. Received progress is permanent in that campaign."),
            ("Host: create an Internet room","Choose Online, then Host a room. Leave Internet · automatic selected and enter a name. Create room & play opens a temporary Cloudflare Internet connection, verifies it and starts the game. No account, VPN, DMZ or port forwarding is needed. This works around Starlink's usual inbound-network restrictions."),
            ("Host: send the invitation","Copy invitation includes a public wss:// relay address, room code and matching settings. Send it privately. Your friend can be in another home or city. Keep the host launcher and Internet connection running; disconnecting or closing the host ends this temporary link."),
            ("Friend: join the room","Choose Online, then Join a room. Enter your name, the host's relay address and the 16-character code. Match the host's visual preset and both sharing choices, select your campaign, then choose Join room & play. Each player has their own ROM setup and can use their own keyboard, controller and soundtrack."),
            ("Meet in the game","Enter the same overworld area or dungeon room, world and floor. Names appear above Links; Show player names is on by default. Eight cosmetic colors identify room slots: green, blue, red, purple, gold, cyan, rose and silver. The room roster shows who joined and whether they are in your area. Menus and transitions temporarily hide avatars."),
            ("Sharing the lantern","Received equipment waits until normal gameplay, after dialogue or inventory closes. Open your inventory to choose the lantern; sharing it does not automatically equip it or make another Link visibly carry it. The HUD shows your own equipped item."),
            ("Free testing service, not guaranteed hosting","Automatic Internet mode uses Cloudflare Quick Tunnels, a free service intended for testing. It has no uptime guarantee and the address changes each time you host. Cloudflare carries the presence traffic. If the helper fails, cancel and create a new room. For a stable address, use Existing relay with your own permanent WSS server; setup is in README.md."),
            ("If you are on the same network","Choose Same network / LAN to skip the Internet service. Copy invitation then uses a LAN address. Allow private-network access if Windows asks. With multiple adapters, select the address on your friend's network. A LAN address will not connect different homes.")],
        2=>[
            ("Shared equipment and campaign progress","With sharing enabled, permanent tools and upgrades, sword/shield/armor, empty bottle ownership, heart capacity/piece progress, dungeon maps/compasses/big keys, pendants, crystals, explored areas, persistent doors, boss-clear flags and story milestones merge. A received acquisition is permanent. Save normally. Opening-sequence and watergate exceptions protect gameplay; some world changes appear when you re-enter an area."),
            ("Shared enemy combat · beta","Optional, off by default; everyone must match. Thirty-two ordinary enemy types share positions, health, death and contributed damage when players are in the same area and floor. The lowest active room slot leads that area's enemy state; another player takes over if the leader leaves. This is an early implementation: jitter, timing and independently spawned enemies can differ. Bosses, NPCs, puzzle objects and projectiles are not synchronized. This is not a complete campaign-wide co-op engine."),
            ("What stays personal","Current health and damage, magic meter, ammunition, rupees, small keys, chest contents, bottle contents, selected tools, position and local saves remain personal. Shared bottles arrive empty. Heart progress converges to the furthest collected total, so two simultaneous different heart pieces are not added together. Avatars have no player collision or reliable depth occlusion. No PvP, chat or shared pause is included."),
            ("Colors and names","The eight colors are cosmetic; acquired armor still changes defense. Color remains assigned after armor upgrades and no longer indicates armor level. Solo keeps original colors. Names support Unicode; very long labels are shortened on screen, with the full name in the launcher roster. Alternate custom sprites are not guaranteed to use the same palette slots."),
            ("Keep room codes private","The room code is an access token. Anyone who knows it and the address can take an open slot. It expires when everyone leaves. The relay sees player positions and avatar pixels; it does not receive ROMs or full save states."),
            ("Disconnects and testing limits","Disconnect leaves your game running in its private campaign. A host's disconnect stops the temporary Internet link. Save normally; continue the saved campaign when creating or joining a new room later. Room invitations expire when empty. There is no automatic reconnect, anti-cheat, rollback or complete multiplayer campaign test. Eight clients on this PC passed network checks through public WSS; the previous release connected you and a friend on separate computers. Version 0.3.0 still needs multi-PC and longer playtesting.")],
        3=>[
            ("Your current controls","The mapping above reflects your current settings. Choose Settings, then Configure controls. Pick a category and click a Keyboard or Controller binding. Press the new input, then Save controls. For controller combinations, hold the first button, press the second and release both. Restore defaults resets the draft; Discard changes leaves your saved controls alone."),
            ("Normal saves and save states","Connect a compatible USB or Bluetooth controller. The controls editor shows its name and live input; button labels use Xbox names. The left stick also moves Link. Every online player can use different controls. Use the game's normal save flow to keep campaign progress. Save states are separate: Shift+F1 through Shift+F10 save a state; F1 through F10 load one by default. Loading a state rewinds progress. Change these shortcuts in Configure controls."),
            ("Where your progress lives","Original solo saves: Game/saves. Original online saves: UserData/Online. Treasure Shuffle solo saves: UserData/Randomizer/<seed ID>/Game/saves; its online campaigns: UserData/Online/Seeds/<seed ID>. The Online campaign selector only shows saves for the selected adventure. Save files are backed up before every launch."),
            ("Close safely","Save in the game, close its window, then close the launcher. Closing the launcher while its game is open is blocked to preserve the session. Disconnect is safe: it stops the network connection and lets the game continue.")],
        4=>[
            ("ROM setup fails","Use an original, unpatched USA ROM. Extract the entire release into a writable folder and keep Game/assets alongside the launcher. Open Activity for the error and Open logs for companion.log. Do not send anyone your ROM or generated assets as a troubleshooting attachment."),
            ("Black screen or graphics trouble","Close the game, choose Crisp pixels and launch again. Smooth 1080p requires OpenGL support. Audio and reduced-flash options are in Settings. Advanced engine options are in Game/zelda3.ini."),
            ("A friend cannot connect","For Internet mode, copy a fresh invitation and keep the host launcher running. The friend needs both the complete wss:// address and room code. A host disconnect ends the link. Starlink needs no port forwarding for this mode. On a LAN, use the host's LAN address, not 127.0.0.1 (the friend's own PC); allow private-network access and avoid guest Wi-Fi isolation."),
            ("Room or settings rejected","Ask the host to copy a new invitation. Empty rooms expire and accept up to eight players. Use version 0.3.1 and match the adventure, ROM assets, gameplay/aspect settings and both sharing choices. For Treasure Shuffle, import the host's recipe and select that seed on Online. The older two-player release cannot join. Saved campaigns can continue in a new room, but the expired invitation cannot be recovered."),
            ("The other Link is missing","Meet in exactly the same area, world and dungeon floor. Menus, transitions and the mode-7 map hide avatars. If the peer connection stops, the avatar times out. Return to Online to check whether frames are arriving."),
            ("Need the technical details?","README.md contains server deployment and build instructions. Validation.txt records what was actually tested and its limits. Source and licenses are included in the package.")],
        6=>[
            ("Choose Music in the launcher","Use Original SNES music, or import an A Link to the Past MSU-1 pack. Choose Import ZIP for a ZIP archive, or Import folder for extracted tracks. Extract .7z and .rar files first. Importing adds a local copy; Use this soundtrack enables your selection on the next launch."),
            ("Music and sound effects","MSU-1 replaces music while normal game sound effects remain. Missing tracks fall back to original music. The page reports standard track coverage. Music volume balances MSU tracks against effects; the Settings audio switch still controls all game audio."),
            ("Standard and extended packs","The native player supports 44100 Hz stereo MSU-1 PCM and 48000 Hz OPUZ. The launcher sets the correct rate and file prefix. Leave MSU Deluxe off unless the author explicitly supplies an extended Deluxe track set. The native port does not need a ROM patch or an .msu intro video."),
            ("Try an orchestral arrangement","The Zeldix A Link to the Past catalogue lists JUD6MENT's Master Orchestral Set (2023) and other packs. Find music packs opens that catalogue. Download only audio you intend to use; retain its artist/curator credits. These third-party files are not bundled in the clean software release."),
            ("Your choice stays personal","Music lives in UserData/Soundtracks, outside solo and online saves. Friends can use different music or the original soundtrack. Relative paths are refreshed on launch, including isolated online campaigns, so moving the portable folder keeps installed music usable."),
            ("Change your mind or repair a pack","Choose Original SNES music, then Use this soundtrack. Imported files remain in your library. If a track goes missing, reimport the same pack; the previous damaged copy is kept as a backup. Settings are backed up before applying a choice. Close the game before importing or changing music.")],
        7=>[
            ("Create your adventure","Set up your original USA ROM on Play, then open Randomizer. Enter a number or phrase, choose Balanced or Surprise, and choose whether to shuffle chest heart pieces. Generate seed adds it to your library. Play selected seed starts its own solo adventure; Launch solo on Play still opens your original adventure."),
            ("Progression protection is mandatory","Treasure Shuffle v1 only moves rupee rewards between 46 ordinary chests. The heart-piece option includes six additional chest locations. Required equipment, all small and big keys, maps, compasses, every big chest, bombs, arrows, bosses, entrances and story events stay original. Pots, shops and farmable rewards also stay original. There is no setting to disable these protections."),
            ("Balanced or Surprise?","Balanced keeps the large rupee rewards together, with smaller rupees and optional pieces in another group. Surprise mixes all eligible rewards. Both preserve the total rewards and the original progression route. Spoiler log lists each eligible room/chest reward; it does not include game assets."),
            ("Use the same seed online","Select the seed, choose Export recipe, and send the small .z3seed.json file to friends. Each imports it using their own USA game data. Choose Use for online, or select the seed in Online adventure. Everyone chooses the same seed and options; the relay refuses different asset hashes. Send the room invitation as usual after creating the room."),
            ("Keep adventures separate","Each seed has its own solo saves and online campaigns. Existing original saves are never copied into a seed. A repeated seed with the same options opens its existing adventure. Save normally; backups are made before launch. To continue online, select that seed first, then its saved campaign. Importing a recipe shares no saves or Nintendo assets."),
            ("Full ALttPR seeds are different","The established ALttP Randomizer at alttpr.com shuffles major equipment and offers logic, goals and entrance options. It produces patched Japanese-ROM games. Those ROM patches and seed codes do not run in this native C engine. Treasure Shuffle is an independent, smaller generator. Do not import an ALttPR ROM as a Companion seed."),
            ("What was actually checked","1,000 seeds across all four option combinations passed byte-for-byte progression checks and reward totals. Actual native chest lookups and reward-receipt routines passed for five fixture seeds. The launcher starts the real game, isolates saves and checks seed data again before launch. A complete randomized solo or co-op campaign has not been played through; existing engine/co-op limitations still apply. RANDOMIZER.md and Validation.txt provide the details.")],
        _=>[
            ("Share the clean release ZIP","Send ZeldaCompanion-0.3.1-win-x64.zip, before ROM setup. It includes the launcher, supporting software, source, licenses and START HERE.html. Everyone must update together. Each recipient initializes it with their own ROM and obtains their own optional music pack. Share Companion seed recipes separately for matching randomized adventures."),
            ("Do not ZIP your installed folder","After setup, Game contains extracted Nintendo data and UserData may contain your saves. The initialized folder is a personal installation, not the clean distributable. Private test recordings are not included in the release."),
            ("Which executable should a friend open?","After Extract All, open Zelda Companion.exe at the top level. START HERE.html is the formatted quick guide; START HERE.txt is a plain-text fallback. Relay/ZeldaRelay.exe is an advanced standalone server, not the game launcher."),
            ("Credits and permissions","Companion/network additions: Carl Prewitt Jr., MIT. Native engine: snesrev and elzo_d; original launcher: RadzPrower. Shader and dependency notices are included in Licenses. This package grants no permission to distribute Nintendo game assets.")]
    };
}
